args.sql:
-- Verify that instrumentref in holdings matches tickersym in funds
SELECT COUNT(*) FROM (
    SELECT h.instrumentref 
    FROM holdings h
    JOIN funds f ON h.instrumentref = f.tickersym
) sub;

