args.sql:
SELECT COUNT(DISTINCT f.tickersym)
FROM funds f
WHERE f.tickersym IN (
    SELECT investmentref FROM risk_metrics WHERE alpha3y > 0
)
AND f.tickersym IN (
    SELECT DISTINCT instrumentref FROM holdings WHERE holdingpct > 0.08
);
